import sys,random,math
sys.path.insert(0,'submission')
from exactcal import calibrate
from exactfabric import Calendar
from exactplan import compile_plan,audit
pf={'groups':1,'jitter_ps':[0],'measurements':[]}
for _ in range(10000):
    N=5;T=random.randrange(1,30);S=random.randrange(1,30);Q=random.randrange(1,6);O=random.randrange(S)
    P=Q*S//math.gcd(T,Q*S)
    if P>100:continue
    F={'n':N,'interval_ns':T,'slice_ns':S,'offset_ns':O,'drift_ppb':[random.randrange(6) for _ in range(N)],'heat':[],'anchors':[], 'links':[],'slices':[[] for _ in range(Q)],'blackouts':[],'guards_ns':[0], 'reconfig_ns':0}
    for a in range(N):
        for b in range(a+1,N):
            lid=len(F['links']);F['links'].append({'ends':[[a,b,0],[b,a,0]],'delay_ns':[random.randrange(1,8*T+1),random.randrange(1,8*T+1)],'defer_rounds':[random.randrange(9),random.randrange(9)]})
            for si in range(Q):
                if random.randrange(2):F['slices'][si].append(lid)
            if random.randrange(3)==0:
                start=random.randrange(P);end=random.randrange(start+1,P+1);F['blackouts'].append([lid,start,end])
    F['anchors']=[[0,0,1]]
    cal=Calendar(pf,F,calibrate(pf))
    assert cal.p==P
    for tick in range(P+32):
        now=O+tick*T;phase=tick%P
        assert cal.slice_at[phase]==now//S%Q and cal.rho[phase]==now%S
        for code in range(2*len(F['links'])):
            src,dst,slot,d,flight,rounds,hop,*_=cal.directions[code]
            blocked=any(l==code//2 and a<=((tick+dt//T)%P)<b for dt in range(d) for l,a,b in F['blackouts'])
            assert blocked==cal.blocked(phase,code)
            if code//2 in F['slices'][cal.slice_at[phase]]:
                margin=min(now%S,S-now%S-d)
                assert margin==cal.margin(phase,code)
    plan=compile_plan(pf,F)
    assert audit(pf,F,plan)=={'valid':True}
print('calendar arbitrary sample periods OK')
PY
